'use strict';
let playerCatalogue=null,playerClubs={},playerCompetitions={},playerDetail=null,playerBusy=false,playerError='',playerLoadId=0,playerQuery='',playerCountry='',playerPosition='',playerScope='known',playerPage=1,playerActiveTab='career';
const playerFeatured=['91845','4592','50175','27992','28003','8198','342229','418560','18922','132098','38253'];
function foldPlayer(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9가-힣ㄱ-ㅎㅏ-ㅣ\u1100-\u11ff]/g,'')}
function playerNation(c){return ({'Korea, South':'South Korea','Korea, North':'North Korea','United States':'USA','Türkiye':'Turkey','Czechia':'Czech Republic','Cote d’Ivoire':'Ivory Coast','Cote d\'Ivoire':'Ivory Coast'})[c]||c}
function playerCountryName(c){return n(playerNation(c))}
function playerPositionName(p){return ({Attack:'공격수',Midfield:'미드필더',Defender:'수비수',Goalkeeper:'골키퍼','Centre-Forward':'중앙 공격수','Right Winger':'오른쪽 윙어','Left Winger':'왼쪽 윙어','Attacking Midfield':'공격형 미드필더','Central Midfield':'중앙 미드필더','Defensive Midfield':'수비형 미드필더','Centre-Back':'중앙 수비수','Left-Back':'왼쪽 풀백','Right-Back':'오른쪽 풀백'})[p]||p||'미수록'}
async function ensurePlayerCatalogue(){if(playerCatalogue||playerBusy)return;playerBusy=true;playerError='';try{let [catalogue,clubs,competitions]=await Promise.all([load('players/index.json'),load('players/clubs.json'),load('players/competitions.json')]);playerCatalogue=catalogue;playerClubs=clubs;playerCompetitions=competitions;for(let p of catalogue.players){p.alias=koreanPlayer(p);if(p.alias===p.name)p.alias='';p.searchKey=foldPlayer(p.name+' '+p.alias);}playerBusy=false;if(state.view==='players'){if(state.selectedPlayer)await selectPlayer(state.selectedPlayer,false);else render()}}catch(e){playerBusy=false;playerError=e.message;if(state.view==='players')render()}}
async function selectPlayer(id,scroll=true){const request=++playerLoadId;state.selectedPlayer=String(id);playerDetail=null;playerError='';save();let entry=playerCatalogue?.players.find(p=>p.id===String(id));if(!entry)return;render();try{let shard=await load('players/part-'+String(entry.shard).padStart(3,'0')+'.json');if(request!==playerLoadId)return;playerDetail=shard[id]?{...shard[id],alias:koreanPlayer(shard[id])}:null;if(!playerDetail)throw Error('선수 상세 자료가 없습니다.');save();if(state.view==='players'){render();const url=new URL(location.href);url.searchParams.set('player',id);url.searchParams.set('date',state.date);history.replaceState(null,'',url);if(scroll)document.querySelector('#playerProfile')?.scrollIntoView({behavior:'smooth',block:'start'})}}catch(e){if(request!==playerLoadId)return;playerError=e.message;render()}}
function playerAge(birth,date){if(!birth||birth>date)return null;let a=+date.slice(0,4)-+birth.slice(0,4);if(date.slice(5)<birth.slice(5))a--;return a}
function visiblePlayerRecords(p){return {transfers:p.transfers.filter(r=>r[0]<=state.date),appearances:p.appearances.filter(r=>r[0]<=state.date)}}
function playerStats(apps){return apps.reduce((s,a)=>({games:s.games+1,minutes:s.minutes+a[3],goals:s.goals+a[4],assists:s.assists+a[5]}),{games:0,minutes:0,goals:0,assists:0})}
function filteredPlayers(){if(!playerCatalogue)return[];const q=foldPlayer(playerQuery),ps=playerCatalogue.players.filter(p=>(!q||p.searchKey.includes(q))&&(!playerCountry||p.country===playerCountry)&&(!playerPosition||p.position===playerPosition)&&(playerScope==='all'||(p.first&&p.first<=state.date)));if(!q&&!playerCountry&&!playerPosition)ps.sort((a,b)=>{let ai=playerFeatured.indexOf(a.id),bi=playerFeatured.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi)||Number(!a.alias)-Number(!b.alias)||(a.alias||a.name).localeCompare(b.alias||b.name,'ko')});return ps}
function playerResultsHTML(){let ps=filteredPlayers(),count=ps.length,per=24,pages=Math.max(1,Math.ceil(count/per));playerPage=Math.min(playerPage,pages);let visible=ps.slice((playerPage-1)*per,playerPage*per);let classics=journeyData.players.filter(p=>(!qForClassic()||foldPlayer(p.name).includes(qForClassic()))&&(!playerCountry||playerNation(playerCountry)===p.country)&&(playerScope==='all'||p.stages[0].date<=state.date)&&!playerCatalogue.players.some(x=>x.alias&&x.alias===p.name));return `${classics.length?'<div class="classic-result-label">클래식 커리어 · 별도 확인한 주요 소속 경로</div><div class="classic-inline-results">'+classics.map(p=>'<button data-classic-player="'+p.id+'">'+esc(p.name)+' ↗</button>').join('')+'</div>':''}<div class="player-results-head"><span>${count.toLocaleString()}명 검색됨 · ${playerCatalogue.meta.playerCount.toLocaleString()}명 수록</span><span>${playerPage} / ${pages} 페이지</span></div><div class="catalogue-grid">${visible.map(p=>`<button class="catalogue-player ${p.id===state.selectedPlayer?'selected':''}" data-player-profile="${p.id}"><div class="catalogue-initial">${esc((p.alias||p.name).slice(0,2))}</div><div><h3 title="${esc(p.name)}">${esc(p.alias||p.name)}</h3><p>${esc(playerCountryName(p.country))} · ${esc(playerPositionName(p.position))}</p><span>${p.first&&p.first<=state.date?'이 날짜 이전의 이력 수록':'이 날짜 이전의 이력 미수록'}</span></div><b>↗</b></button>`).join('')||'<div class="empty">조건에 맞는 선수가 없습니다.<br>영문 이름, 다른 날짜 또는 전체 선수 범위를 사용해 보세요.</div>'}</div><div class="player-pagination"><button data-player-page="-1" ${playerPage<=1?'disabled':''}>← 이전</button><span>${playerPage} / ${pages}</span><button data-player-page="1" ${playerPage>=pages?'disabled':''}>다음 →</button></div>`}
function playerControls(){let countries=[...new Set(playerCatalogue.players.map(p=>p.country).filter(Boolean))].sort((a,b)=>playerCountryName(a).localeCompare(playerCountryName(b),'ko'));return `<div class="catalogue-controls"><div class="catalogue-search"><span>⌕</span><input id="playerSearch" type="search" value="${esc(playerQuery)}" placeholder="선수 검색 · 손흥민, Messi, Mbappe, Modric…" aria-label="선수 이름 검색"></div><div class="catalogue-filters"><label>국적 (프로필)<select id="playerCountry"><option value="">모든 국적</option>${countries.map(c=>`<option value="${esc(c)}" ${c===playerCountry?'selected':''}>${esc(playerCountryName(c))}</option>`).join('')}</select></label><label>포지션 (프로필)<select id="playerPosition"><option value="">모든 포지션</option>${['Attack','Midfield','Defender','Goalkeeper'].map(v=>`<option value="${v}" ${v===playerPosition?'selected':''}>${playerPositionName(v)}</option>`).join('')}</select></label><label>탐색 범위<select id="playerScope"><option value="known" ${playerScope==='known'?'selected':''}>이 날짜까지 이력이 확인되는 선수</option><option value="all" ${playerScope==='all'?'selected':''}>전체 선수 · 미래 이력은 계속 숨김</option></select></label></div><div class="popular-searches"><span>빠른 검색</span>${[['손흥민','손흥민'],['박지성','박지성'],['김민재','김민재'],['메시','메시'],['호날두','호날두'],['홀란','홀란']].map(([q,t])=>`<button data-player-query="${q}">${t}</button>`).join('')}<button data-view="journeys">클래식 선수 성장 경로 ↗</button></div></div>`}
function playersView(){if(!playerCatalogue){if(!playerBusy)queueMicrotask(ensurePlayerCatalogue);return `<div class="player-banner"><div class="eyebrow">EVERY PLAYER HAS A PATH</div><h2>이름 뒤에 쌓인, 수많은 시즌.</h2><p>선수 검색과 날짜별 커리어를 준비하고 있습니다.</p></div><div class="loading">${playerError?esc(playerError):'50,000명 이상의 선수 목록을 불러오는 중…'}</div>${playerError?'<button class="primary" id="retryPlayers">다시 시도</button>':''}`};let meta=playerCatalogue.meta;return `<section class="player-banner"><div><div class="eyebrow">EVERY PLAYER HAS A PATH</div><h2>그날, 이 선수는 어디에 있었을까.</h2><p>실제 이동과 출전 기록을 선택한 날짜까지 펼쳐봅니다.</p></div><div class="player-count"><b>${meta.playerCount.toLocaleString()}</b><span>PLAYER PROFILES</span></div></section><div class="player-data-strip"><span><b>${meta.withHistory.toLocaleString()}</b>명 커리어 기록</span><span><b>${meta.transferCount.toLocaleString()}</b>건 이동 기록</span><span><b>${meta.appearanceCount.toLocaleString()}</b>건 실제 출전 기록</span></div>${playerControls()}<div id="playerResults">${playerResultsHTML()}</div><section id="playerProfile">${state.selectedPlayer?(playerDetail?playerProfileHTML(playerDetail):`<div class="loading">${playerError?esc(playerError):'선수의 커리어를 불러오는 중…'}</div>`):'<div class="profile-placeholder"><span>↖</span><h3>선수를 선택해 커리어를 열어보세요.</h3><p>미래 이적과 현재의 누적 기록을 과거 화면에 끼워 넣지 않습니다.</p></div>'}</section><p class="translation-note">이름은 확인된 한국어 표기를 우선 표시합니다. 한글 표기가 없는 선수는 원문 이름을 유지하며, 원문 이름으로도 검색할 수 있습니다.</p><div class="notice"><b>수록 범위 안내</b> ${esc(meta.note)} 50,149명 중 날짜가 있는 이적 또는 출전 기록이 있는 선수는 ${meta.withHistory.toLocaleString()}명입니다. 자료가 없는 선수와 시즌은 미수록이라고 표시합니다. 국적·포지션은 원본 프로필 시점의 참고 정보이며 당시 대표팀·포지션의 확정 기록이 아닙니다. 출전 자료는 ${meta.appearanceThrough}까지, 자료 전체 기준은 ${meta.snapshot}입니다.</div>`}
function playerClubName(id){const c=playerClubs[id];return n(c?.name||'클럽 #'+id)}
function recentPlayerEvidence(p,records){let events=[...records.transfers.map(t=>({date:t[0],club:t[2],clubId:t[4],kind:'이동 기록'})),...records.appearances.map(a=>({date:a[0],club:playerClubName(a[1]),clubId:a[1],kind:'출전 기록'}))];events.sort((a,b)=>b.date.localeCompare(a.date));if(!events.length)return null;let latest=events.filter(e=>e.date===events[0].date),clubs=[...new Set(latest.map(e=>e.club))];return {date:events[0].date,clubs,clubId:events[0].clubId,kind:events[0].kind}}
function playerProfileHTML(p){const records=visiblePlayerRecords(p),stats=playerStats(records.appearances),age=playerAge(p.birth,state.date),last=recentPlayerEvidence(p,records),watched=(state.playerWatch||[]).includes(p.id),country=playerNation(p.country),meta=playerCatalogue.meta;return `<article class="detailed-player"><div class="player-profile-top"><div class="player-profile-identity"><div class="profile-monogram">${esc((p.alias||p.name).slice(0,2))}</div><div><div class="eyebrow">PLAYER DOSSIER · ${state.date}</div><h2>${esc(p.alias||p.name)}</h2><p>${esc(playerCountryName(p.country))}${age!==null?' · 당시 '+age+'세':''}</p></div></div><div class="player-profile-actions"><button data-watch-player="${p.id}" class="year-bookmark">${watched?'★ 저장한 선수':'☆ 선수 저장'}</button>${manifest.nations?.[country]?`<button data-nation-view="${esc(country)}" class="text-button">${esc(n(country))} 대표팀 ↗</button>`:''}</div></div><div class="player-evidence"><span>이 날짜까지 가장 최근에 확인되는 소속 기록</span><b>${last?teamLabel(last.clubs.map(n).join(' / '),{id:last.clubId}):'이 날짜 이전 소속 이력 미수록'}</b><small>${last?last.date+' · '+last.kind:'최신 프로필 소속을 과거 소속으로 대체하지 않았습니다.'}</small></div>${state.date>meta.snapshot?`<div class="stale-player-notice">자료 갱신은 ${meta.snapshot}에 중단됐습니다. 그 이후의 이적·출전은 확인할 수 없습니다.</div>`:''}<div class="personal-stats"><div><strong>${stats.games}</strong><span>수록 출전 기록</span></div><div><strong>${stats.minutes.toLocaleString()}</strong><span>출전 시간 · 분</span></div><div><strong>${stats.goals}</strong><span>기록된 득점</span></div><div><strong>${stats.assists}</strong><span>기록된 도움</span></div></div><p class="note">선택한 날짜까지 이 데이터에 수록된 경기만 합산합니다. 개인의 전체 통산 기록이 아닙니다. ${esc(playerPositionName(p.detailPosition))} · 생년월일 ${p.birth||'미수록'} (참고 프로필)</p><div class="player-profile-tabs">${[['career','소속·이동'],['stats','연도별 출전'],['matches','최근 실제 출전']].map(([k,t])=>`<button data-player-tab="${k}" class="${playerActiveTab===k?'active':''}">${t}</button>`).join('')}<a href="${esc(p.source)}" target="_blank" rel="noopener">원본 프로필 · 미래 정보 주의 ↗</a></div><div class="player-tab-content">${playerActiveTab==='career'?playerCareerHTML(p,records):playerActiveTab==='stats'?playerAnnualHTML(records.appearances):playerMatchesHTML(records.appearances)}</div></article>`}
function playerCareerHTML(p,records){if(!records.transfers.length)return '<div class="empty">이 날짜까지의 이동 기록이 수록되지 않았습니다.<br>출전 기록이 있는 경우 ‘연도별 출전’에서 확인할 수 있습니다.</div>';const groups={};for(let t of records.transfers)(groups[t[0]]??=[]).push(t);return `<div class="transfer-career">${Object.entries(groups).sort((a,b)=>b[0].localeCompare(a[0])).map(([date,ts])=>`<div class="career-date-group"><time>${date}</time><div>${ts.map(t=>`<article class="career-transfer"><div><span>${teamLabel(t[1],{id:t[3]})}</span><b>→</b><strong>${teamLabel(t[2],{id:t[4]})}</strong></div><small>소속 이동·등록 기록${ts.length>1?' · 같은 날짜의 이동 순서 미확정':''}</small></article>`).join('')}</div></div>`).join('')}</div><p class="note">원본의 등록·이동 날짜입니다. 계약 발표 날짜와 다를 수 있습니다. 유소년 승격, 임대 복귀 및 은퇴·무소속 기록도 원본에 따라 포함되며, 근거 없이 영구 이적·자유 계약으로 구분하지 않습니다. 이적료는 미상과 0원의 구분 문제로 표시하지 않습니다.</p>`}
function playerAnnualHTML(apps){let groups={};for(let a of apps){let key=a[0].slice(0,4)+'|'+a[1]+'|'+a[2];let row=groups[key]??={year:a[0].slice(0,4),club:a[1],comp:a[2],games:0,minutes:0,goals:0,assists:0};row.games++;row.minutes+=a[3];row.goals+=a[4];row.assists+=a[5]}let rows=Object.values(groups).sort((a,b)=>b.year.localeCompare(a.year)||a.club.localeCompare(b.club));if(!rows.length)return '<div class="empty">이 날짜까지 개인 출전 자료가 없습니다. 이적 기록과 별개로 표시합니다.</div>';return `<p class="note">달력 연도·소속·대회별 집계입니다. 리그의 2020/21 같은 시즌 구분과 다릅니다. ${state.date} 이후 경기와 최신 누적 통계는 제외합니다.</p><div class="table-wrap"><table><thead><tr><th>연도</th><th>클럽·대표팀</th><th>대회</th><th>수록 경기</th><th>시간</th><th>득점</th><th>도움</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.year}</td><td>${teamLabel(playerClubName(r.club),{id:r.club})}</td><td>${esc(koreanCompetition(r.comp))}</td><td>${r.games}</td><td>${r.minutes}′</td><td>${r.goals}</td><td>${r.assists}</td></tr>`).join('')}</tbody></table></div>`}
function playerMatchesHTML(apps){if(!apps.length)return '<div class="empty">이 날짜 이전의 실제 출전 기록이 없습니다.</div>';return `<div class="table-wrap"><table><thead><tr><th>경기일</th><th>당시 출전 소속</th><th>대회</th><th>출전 시간</th><th>득점</th><th>도움</th></tr></thead><tbody>${apps.slice(-50).reverse().map(a=>`<tr><td><button data-goto="${a[0]}" class="text-button">${a[0]} ↗</button></td><td>${teamLabel(playerClubName(a[1]),{id:a[1]})}</td><td>${esc(koreanCompetition(a[2]))}</td><td>${a[3]}′</td><td>${a[4]}</td><td>${a[5]}</td></tr>`).join('')}</tbody></table></div><p class="note">최근 수록 출전 최대 50건. 날짜를 선택하면 해당 날짜의 역사 화면으로 이동합니다.</p>`}
function updatePlayerResults(){if(!playerCatalogue)return;const el=document.querySelector('#playerResults');if(el)el.innerHTML=playerResultsHTML()}
let playerSearchTimer=null;
document.addEventListener('input',e=>{if(e.target.id==='playerSearch'){playerQuery=e.target.value;playerPage=1;clearTimeout(playerSearchTimer);playerSearchTimer=setTimeout(updatePlayerResults,100)}});
document.addEventListener('change',e=>{if(['playerCountry','playerPosition','playerScope'].includes(e.target.id)){if(e.target.id==='playerCountry')playerCountry=e.target.value;if(e.target.id==='playerPosition')playerPosition=e.target.value;if(e.target.id==='playerScope')playerScope=e.target.value;playerPage=1;updatePlayerResults()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.playerProfile){selectPlayer(b.dataset.playerProfile)}else if(b.dataset.playerPage){playerPage+=+b.dataset.playerPage;updatePlayerResults()}else if(b.dataset.playerQuery){playerQuery=b.dataset.playerQuery;playerScope='all';playerCountry='';playerPosition='';playerPage=1;render()}else if(b.dataset.playerTab){playerActiveTab=b.dataset.playerTab;document.querySelector('#playerProfile').innerHTML=playerProfileHTML(playerDetail)}else if(b.dataset.watchPlayer){state.playerWatch??=[];state.playerWatch=state.playerWatch.includes(b.dataset.watchPlayer)?state.playerWatch.filter(x=>x!==b.dataset.watchPlayer):[...state.playerWatch,b.dataset.watchPlayer];save();document.querySelector('#playerProfile').innerHTML=playerProfileHTML(playerDetail);toast('선수 저장 상태를 변경했습니다.')}else if(b.id==='retryPlayers'){playerError='';ensurePlayerCatalogue()}});

function qForClassic(){return foldPlayer(playerQuery)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.classicPlayer){state.player=b.dataset.classicPlayer;state.view='journeys';render()}});
